"""Targeted final prose review; replaces identified chronological bridge paragraphs."""
from pathlib import Path
import re
ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT/'docs/dissertation/condensed_translated_humanized_ukrainian'

def paragraph(text,start,replacement):
    return re.sub(r'(?m)^'+re.escape(start)+r'[^\n]*',lambda _:replacement,text,count=1)
def main():
    p=SRC/'04_CHAPTER_3.md';s=p.read_text(encoding='utf-8')
    s=paragraph(s,'Основна експериментальна програма змінює форму контексту','Дослідження структури контексту встановлює, як заданий пакет впливає на доступну інформацію. Для виконуваного предиктора потрібно також визначити, як цей пакет формується з кадрів, як за вмістом вибираються деталі та як обчислюються градієнти за обмеженої пам’яті. Сталі просторові області ізолюють працездатність компактного подання; адаптивний маршрут перевіряє інший спосіб членства; реверсивне ядро змінює збереження активацій. Ці механізми пов’язані спільним інтерфейсом, але кожний потребує власного контрольованого зіставлення.')
    s=s.replace('Після фіксації цієї програми поставлено окреме питання:','Звідси випливає питання композиції:')
    s=s.replace('Попередній прототип нижче перевіряв ці зв’язки','Предиктор зі сталими ділянками перевіряє ці зв’язки')
    p.write_text(s,encoding='utf-8')
    p=SRC/'05_CHAPTER_4.md';s=p.read_text(encoding='utf-8')
    s=paragraph(s,'Основні результати отримано в окремих причинних програмах','Структура пакета визначає доступну інформацію, але його практична вартість залежить від реалізації предиктора. Тому тут зіставляються три властивості: працездатність компактного просторового подання, витрати диференціювання та якість прогнозу на двох задачах. Експеримент зі сталими ділянками дає виміряний приклад компактного інтерфейсу. Контракт адаптивного пакування й внутрішнього реверсивного ядра (§3.7) потребує окремих числових і ресурсних перевірок; показники різних виконуваних динамік залишаються розділеними.')
    s=paragraph(s,'Попередні результати відповіли на два окремі запитання','Можливість зберігати довшу історію та можливість відтворювати активації не гарантують працездатності їх композиції. Просторовий інтерфейс повинен справді обмежувати живий стан і залишати достатньо інформації декодеру. Перевірка зі сталими ділянками ізолює цю вимогу від складності навчання членства деталей. Її результат характеризує компактне подання за заданого протоколу Moving MNIST, тоді як структура тривалого контексту досліджується на TRB.')
    s=s.replace('Перший прототип використовував','Варіант із жорсткою маршрутизацією використовував')
    s=s.replace('Подальший дослід перейшов до фіксованої геометрії ділянок. Такий вибір відокремив перевірку сумісності від невирішеної задачі навчання політики маршрутизації.','Фіксована геометрія ділянок дає контрольний спосіб відокремити працездатність подання від навчання політики маршрутизації.')
    s=s.replace('У попередньому прототипі','У предикторі зі сталими ділянками').replace('попереднього інтегрованого прототипу','інтегрованого предиктора з часовою рекурентністю')
    s=s.replace('Основні твердження все ще спираються','Основні твердження спираються').replace('усуває попередню прогалину на рівні технічної здійсненності','перевіряє технічну здійсненність композиції').replace('не дозволяє переносити на неї підтверджувальні висновки TRB','не дозволяє переносити на цю модель підтверджувальні висновки TRB')
    s=s.replace('Перший жорсткий вибір ділянок','Жорсткий вибір ділянок').replace('і тому став придатною вихідною точкою','і є прикладом компактного інтерфейсу')
    # Conditional rather than universal algorithmic prescription.
    s=s.replace('доцільним є просторово ієрархічний або часово проріджений контекст','кандидатом для перевірки є просторово ієрархічний або часово проріджений контекст').replace('перевагу має щільний плоский контекст','щільний плоский контекст є важливим контрольним кандидатом')
    s=s.replace('## 4.10 Правило вибору методу на системному рівні\n\n','## 4.10 Правило вибору методу на системному рівні\n\nСинтез поєднує встановлені ефекти з умовами їх застосування. Незаповнені структурні та інтегровані вимірювання не підтримують рекомендації самі по собі: відповідні гілки правила залишаються перевірними кандидатами. Змішані напрями FRT не дозволяють звести всі бюджети до однієї монотонної межі.\n\n')
    p.write_text(s,encoding='utf-8')
    # Front matter and chapter conclusions frame dimensions without future victory.
    p=SRC/'00_FRONT_MATTER.md';s=p.read_text(encoding='utf-8')
    at=s.index('## English') if '## English' in s else -1
    ua='Структуру ієрархії досліджено через місткість, розподіл між рівнями, часову підтримку, просторову деталізацію та перекриття. Для адаптивного предиктора окремо визначено перевірки числової коректності, ресурсів і якості; комірки без вимірювань не входять до підтверджених висновків.\n\n'
    # Add within abstract before keywords, preserving the established abstract layout.
    s=s.replace('**Ключові слова:**',ua+'**Ключові слова:**',1)
    en='Hierarchy is examined through capacity, allocation across scales, temporal support, spatial detail and overlap. Numerical correctness, resource use and predictive quality have separate validation protocols; unmeasured results do not support empirical conclusions.\n\n'
    s=s.replace('**Keywords:**',en+'**Keywords:**',1)
    p.write_text(s,encoding='utf-8')
    print('Rewrote scientific transitions, synthesis conditions and abstracts.')
if __name__=='__main__':main()
